from __future__ import annotations

from typing import Literal, List, TypedDict, Unpack, Optional

from ...base.client import BaseClient
from ....client.decorators import api_version_check


class ConferenceMember(TypedDict):
    role: Literal["moderator", "speaker"]


class ConferenceRole(TypedDict):
    permissions: int


class ConferenceUpdateKwargs(TypedDict, total=False):
    name: str
    type: Literal["equitable", "webinar"]
    creator: str
    members: dict[str, ConferenceMember]
    roles: dict[str, ConferenceRole]


class ConferenceNewCreateKwargs(TypedDict, total=False):
    type: Literal["equitable", "webinar"]
    pinRequired: Optional[bool]
    members: dict[str, ConferenceMember]
    roles: dict[str, ConferenceRole]


class ConferencesMethods(BaseClient):
    """
    Методы группы 'Конференции' из https://im-docs.corp.mail.ru/
    """

    @api_version_check(min_version=8, max_version=99)
    async def rapi_conference_create(
        self,
        name: str,
        _type: Literal["equitable", "webinar"],
        participants: List[str],
        callParticipants: bool,
        pinRequired: bool,
    ) -> dict:
        """
        Создание новой конференции

        :param name: Название конференции
        :param _type: Тип конференции (равноправная или вебинар)
        :param participants: Список участников конференции (sn'ы),
        которым нужно отправить ссылку на конференцию от имени пользователя,
        создающего конференцию.
        :param pinRequired:
        :param callParticipants: Нужно ли выполнять обратный
        звонок всем участникам конференции.
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/conference/create",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "name": name,
                    "type": _type,
                    "participants": participants,
                    "callParticipants": callParticipants,
                    "pinRequired": pinRequired,
                },
            },
        )

    @api_version_check(min_version=103)
    async def rapi_conference_get(self, conference_id: str) -> dict:
        """
        Запросить параметры конференции
        Запрос параметров конференции
        :param conference_id: ID конференции
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/conference/get",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"id": conference_id},
            },
        )

    @api_version_check(min_version=103)
    async def rapi_conference_update(self, conference_id: str, **kwargs: Unpack[ConferenceUpdateKwargs]) -> dict:
        """
        Обновить параметры конференции
        Обновление параметров конференции
        :param conference_id: ID конференции.
        :param name: Название конференции
        :param conf_type:
        :param creator: SN создателя конференции.
        :param members: role string example: speaker Роль участника
        :param roles: permissions number example: 42 Битовая маска, содержащая набор разрешений для данной роли:
        * Управление параметрами конференции - 1
        * Управление медиа - 2
        * Управление комнатой ожидания - 4
        * Удаление участников - 8
        * Управление записью звонка - 16
        * Отправка аудио - 32
        * Отправка видео - 64
        * Демонстрация экрана - 128
        * Просмотр реакций - 256
        * Отправка реакций - 512
        * Просмотр сообщений в чате - 1024
        * Отправка сообщений в чат - 2048
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/conference/update",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"id": conference_id, **kwargs},
            },
        )

    @api_version_check(min_version=100)
    async def rapi_conference_create_new(self, name: str, **kwargs: Unpack[ConferenceNewCreateKwargs]) -> dict:
        """
        Создание новой конференции

        :param name: Название конференции
        :param _type: Тип конференции (равноправная или вебинар)
        :param pinRequired:
        :param members: role string example: speaker Роль участника
        :param roles: permissions number example: 42 Битовая маска, содержащая набор разрешений для данной роли:
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/conference/create",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"name": name, **kwargs},
            },
        )
